<script>
 import {spring} from 'svelte/motion';import {onDestroy} from 'svelte';import {leaves,vpd,et0,dli,profiles} from '$lib/engines/agronomy.js';import {insects,playTone,stopTone,listen} from '$lib/engines/audio.js';import {openCamera,sampleLeaf} from '$lib/engines/vision.js';import {saveRecord,getRecords} from '$lib/db/ledger.js';
 const nav=[['◉','Leaf lab'],['⌁','Bio radar'],['◌','VPD architect'],['⌖','NPK planner'],['⌘','Field vault']];let page='Leaf lab',theme='Canopy obsidian',role='Home gardener',sim=leaves[0],temp=25,rh=62,offset=-1.5,ppfd=480,hours=12,crop='Tomato',activeInsect=insects[0],toneOff=null,permission='SIMULATOR ACTIVE',records=0,modal='',isMobile=false,live=false;let videoElement,scanCanvas,mediaStream,scanTimer,micContext,micAnalyser,micStream,micTimer;let meter=spring(46.8,{stiffness:.16,damping:.66});$: currentVpd=vpd(+temp,+rh,+offset);$: water=et0(+temp,+rh);$: light=dli(+ppfd,+hours);$: meter.set(sim.spad);$:{if(typeof window!=='undefined')isMobile=window.innerWidth<700}onDestroy(()=>{stopTone();if(mediaStream)mediaStream.getTracks().forEach(t=>t.stop());if(scanTimer)clearInterval(scanTimer);if(micTimer)clearInterval(micTimer);if(micStream)micStream.getTracks().forEach(t=>t.stop());if(micContext)micContext.close()});
 function chooseLeaf(x){sim=x;meter.set(x.spad);saveRecord({type:'leaf',...x}).then(getRecords).then(r=>records=r.length)}async function startCamera(){try{if(!videoElement)return;mediaStream=await openCamera(videoElement);permission='CAMERA ACTIVE';live=true;modal='Leaf analysis';scanTimer=setInterval(()=>{if(!videoElement?.videoWidth||!scanCanvas)return;const ctx=scanCanvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(videoElement,0,0,100,100);const s=sampleLeaf(ctx,20,20,60,60);const spad=Math.max(0,Math.min(60,s.spad));sim={name:'Live camera sample',spad,vari:s.vari,blight:s.necrotic,status:spad<26?'Low greenness':spad<36?'Check chlorosis':'Color estimate',tone:spad<26?'warn':'good',detail:'Pixel-color estimate from the camera ROI; not a calibrated SPAD or pathology diagnosis.'};meter.set(spad)},1000)}catch{permission='CAMERA PERMISSION REQUIRED'}}async function startMic(){try{micStream=await listen();micContext=new AudioContext();micAnalyser=micContext.createAnalyser();micAnalyser.fftSize=8192;micContext.createMediaStreamSource(micStream).connect(micAnalyser);permission='MICROPHONE ACTIVE';live=true;micTimer=setInterval(()=>{const bins=new Uint8Array(micAnalyser.frequencyBinCount);micAnalyser.getByteFrequencyData(bins);const rate=micContext.sampleRate,lo=Math.ceil(80/(rate/micAnalyser.fftSize)),hi=Math.min(bins.length-1,Math.floor(3500/(rate/micAnalyser.fftSize)));let peak=lo;for(let j=lo+1;j<=hi;j++)if(bins[j]>bins[peak])peak=j;const hz=Math.round(peak*rate/micAnalyser.fftSize);if(bins[peak]>8){const match=insects.reduce((a,b)=>Math.abs(b.hz-hz)<Math.abs(a.hz-hz)?b:a,insects[0]);activeInsect={...match,hz};}},180)}catch{permission='MIC PERMISSION REQUIRED'}}function play(i){activeInsect=i;stopTone();playTone(i.hz,i.wave);live=true}function setTheme(e){theme=e.target.value;document.body.dataset.theme=theme}function exportCsv(){const rows=[['createdAt','type','name','spad'],...(records?[['Local ledger','records',records,'']]:[])];const blob=new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='terra-field-ledger.csv';a.click()}
</script>
<svelte:head><title>Terra-Spectra — Field intelligence</title><meta name="description" content="Offline-ready plant health, microclimate and bio-acoustic field intelligence."/></svelte:head>
<div class="shell"><video bind:this={videoElement} class="camera-source" class:camera-visible={modal==='Leaf analysis'&&permission==='CAMERA ACTIVE'} autoplay playsinline muted></video><canvas bind:this={scanCanvas} width="100" height="100" class="camera-canvas"></canvas><header class="topbar"><a class="brand" href="/" aria-label="Terra-Spectra home"><span class="brandmark">✳</span><span>TERRA<span class="brand-dash">—</span>SPECTRA<small>FIELD INTELLIGENCE SYSTEM</small></span></a><div class="header-right"><span class="live-pill"><i></i> FIELD SYSTEM ONLINE</span><label class="theme-select"><span>ENVIRONMENT</span><select bind:value={theme} on:change={setTheme}><option>Canopy obsidian</option><option>Field daylight frost</option><option>Grow-room magenta</option><option>Eco-glass</option></select></label><button class="icon-button" on:click={()=>modal='Privileges'} title="Privileges">♙</button><a class="download" href="https://github.com/kennedy-blip/terra-spectra/releases/latest/download/TerraSpectra-AgroLab-v1.0.0.apk" download="TerraSpectra-AgroLab-v1.0.0.apk" on:click={()=>modal='APK center'} aria-label="Download Terra-Spectra Android APK"><span>↓</span> Get Android app</a><button class="mobile-menu" on:click={()=>isMobile=!isMobile}>☰</button></div></header>
<div class="layout"><aside class:show={isMobile}><div class="side-label">WORKSPACE <span>01 / 05</span></div><div class="nav-list">{#each nav as item,i}<button class:active={page===item[1]} on:click={()=>{page=item[1];isMobile=false}}><span class="nav-icon">{item[0]}</span>{item[1]}{#if item[1]==='Field vault'}<b class="admin-tag">PRO</b>{/if}</button>{/each}</div><div class="side-bottom"><div class="device-card"><div class="device-icon">⌁</div><div><strong>Sensor array</strong><small>{permission}</small></div><span class="pulse-dot"></span></div><div class="profile"><div class="avatar">TS</div><div><strong>Field operator</strong><small>{role}</small></div><button on:click={()=>modal='Privileges'}>···</button></div></div></aside>
<main><div class="page-heading"><div><div class="eyebrow"><span>FIELD OVERVIEW</span><span class="slash">/</span><span>{page.toUpperCase()}</span></div><h1>{page==='Leaf lab'?'Plant health, in focus.':page==='Bio radar'?'Listen to the living field.':page==='VPD architect'?'Read the atmosphere.':page==='NPK planner'?'Feed with precision.':'Your field, remembered.'}</h1><p>{page==='Leaf lab'?'Optical chlorophyll estimation and early stress signals, in one place.':page==='Bio radar'?'Identify wingbeat signatures and protect the beneficials.':page==='VPD architect'?'Translate temperature, humidity and light into actionable crop demand.':page==='NPK planner'?'A measured nutrient starting point, tailored to your crop.':'A private, offline-first record of your observations.'}</p></div><button class="date-chip">◷ &nbsp; {new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})} <span>⌄</span></button></div>
{#if page==='Leaf lab'}<section class="overview-grid"><article class="card hero-card"><div class="card-top"><div><div class="eyebrow">OPTICAL SPECTROMETER <span class="badge">LIVE ENGINE</span></div><h2>Chlorophyll index</h2></div><button class="kebab" aria-label="More options">···</button></div><div class="meter-row"><div class="meter"><div class="meter-track"><div class="meter-fill" style={`height:${$meter/60*100}%`}></div><div class="meter-tick t1"></div><div class="meter-tick t2"></div></div><div class="meter-number">{$meter.toFixed(1)}<small>SPAD</small></div></div><div class="health-summary"><span class="status-tag {sim.tone}"><i></i>{sim.status}</span><h3>{sim.name}</h3><p>{sim.detail}</p><div class="metric-pair"><div><small>VARI INDEX</small><strong>{sim.vari>0?'+':''}{sim.vari.toFixed(2)}</strong></div><div><small>BLIGHT AREA</small><strong>{sim.blight.toFixed(1)}<em>%</em></strong></div></div><button class="outline-button" on:click={()=>modal='Leaf analysis'}>View leaf analysis <span>↗</span></button></div></div><div class="scale-line"><span>0</span><div><i></i><i></i><i></i><i></i><i></i></div><span>60</span></div><div class="scale-caption"><span>SEVERE STRESS</span><span>HEALTHY RANGE</span></div></article>
<article class="card condition-card"><div class="card-top"><div><div class="eyebrow">MICROCLIMATE <span class="live-text">● LIVE</span></div><h2>Field conditions</h2></div><span class="weather">☀</span></div><div class="conditions"><div class="condition"><span class="condition-icon amber">☼</span><div><small>AIR TEMPERATURE</small><strong>{temp}<em>°C</em></strong></div><span class="trend">↗ 1.2°</span></div><div class="condition"><span class="condition-icon blue">◌</span><div><small>RELATIVE HUMIDITY</small><strong>{rh}<em>%</em></strong></div><span class="trend neutral">STABLE</span></div><div class="condition"><span class="condition-icon green">⌁</span><div><small>VAPOR PRESSURE DEFICIT</small><strong>{currentVpd.toFixed(2)}<em>kPa</em></strong></div><span class="status-tag small-tag {currentVpd>1.6?'warn':'good'}"><i></i>{currentVpd>1.6?'HIGH':'OPTIMAL'}</span></div></div><div class="condition-foot"><span>◉ &nbsp; Estimated from local inputs</span><button on:click={()=>page='VPD architect'}>Tune conditions ↗</button></div></article>
<article class="card scan-card"><div class="card-top"><div><div class="eyebrow">QUICK SCAN</div><h2>Choose a leaf profile</h2></div><span class="round-icon">⌁</span></div><div class="sim-list">{#each leaves as leaf,i}<button class:chosen={sim.name===leaf.name} class="sim-row" on:click={()=>chooseLeaf(leaf)}><span class="leaf-icon" class:yellow={leaf.tone==='warn'} class:brown={leaf.tone==='bad'}>✳</span><span><strong>{leaf.name}</strong><small>{leaf.spad.toFixed(1)} SPAD <i>·</i> {leaf.blight}% stress</small></span><span class="row-arrow">↗</span></button>{/each}</div><button class="camera-button" on:click={startCamera}>▣ &nbsp; {live?'Camera / mic ready':'Start live camera scan'} <span>→</span></button></article>
<article class="card radar-card"><div class="card-top"><div><div class="eyebrow">BIO-ACOUSTIC RADAR <span class="badge">FFT CLASSIFIER</span></div><h2>Wingbeat signatures</h2></div><button class="kebab">···</button></div><div class="radar-content"><div class="radar-visual"><div class="radar-ring r1"></div><div class="radar-ring r2"></div><div class="radar-ring r3"></div><div class="radar-sweep"></div><div class="radar-center">⌁</div><span class="radar-point p1"></span><span class="radar-point p2"></span><span class="radar-point p3"></span></div><div class="radar-readout"><div class="eyebrow">CURRENT LOCK</div><strong>{activeInsect.name}</strong><div class="frequency">{activeInsect.hz.toLocaleString()} <span>Hz · f₀</span></div><span class="status-tag {activeInsect.hz===108?'bad':'good'}"><i></i>{activeInsect.kind}</span><div class="waveform">{#each Array(34) as _,i}<i style={`height:${9+Math.abs(Math.sin(i*.65))*30+Math.random()*12}px`}></i>{/each}</div></div></div><div class="insect-list">{#each insects as insect,i}<button class:chosen={activeInsect===insect} on:click={()=>play(insect)}><span class="insect-dot" class:danger={insect.hz===108||insect.hz>2000}></span>{insect.name}<small>{insect.hz} Hz</small></button>{/each}</div><button class="text-button" on:click={startMic}>◉ &nbsp; {permission==='MICROPHONE ACTIVE'?'Microphone FFT active':'Enable live microphone FFT'} <span>↗</span></button></article></section>
{:else if page==='VPD architect'}<section class="module-grid"><article class="card module-main"><div class="card-top"><div><div class="eyebrow">PENMAN–MONTEITH · TETENS</div><h2>VPD & evapotranspiration</h2></div><span class="badge">OFFLINE MIRROR</span></div><div class="big-reading">{currentVpd.toFixed(2)} <small>kPa</small><span class="status-tag {currentVpd>.4&&currentVpd<1.5?'good':'warn'}"><i></i>{currentVpd>.4&&currentVpd<1.5?'GROWTH WINDOW':'CHECK CONDITIONS'}</span></div><div class="chart"><div class="chart-label">VAPOR PRESSURE DEFICIT · kPa</div><div class="chart-grid"><span>2.0</span><span>1.5</span><span>1.0</span><span>0.5</span><div class="chart-line"></div><div class="crosshair" style={`left:${rh}%;top:${Math.max(8,90-currentVpd*40)}%`}></div><div class="cross-value">{currentVpd.toFixed(2)}</div></div><div class="axis">0% RH <span>RELATIVE HUMIDITY</span> 100%</div></div><div class="result-row"><div><small>ET₀ ESTIMATE</small><strong>{water.toFixed(2)} <em>mm/day</em></strong></div><div><small>DAILY LIGHT INTEGRAL</small><strong>{light.toFixed(1)} <em>mol/m²/day</em></strong></div><div><small>WATER DEMAND</small><strong>{water.toFixed(1)} <em>L/m²/day</em></strong></div></div></article><article class="card controls"><div class="eyebrow">ENVIRONMENT INPUTS</div><h2>Shape the forecast</h2><label class="slider-label">Air temperature <b>{temp} °C</b><input type="range" min="8" max="42" bind:value={temp}/></label><label class="slider-label">Relative humidity <b>{rh}%</b><input type="range" min="20" max="95" bind:value={rh}/></label><label class="slider-label">Leaf temperature offset <b>{offset} °C</b><input type="range" min="-5" max="4" step="0.5" bind:value={offset}/></label><label class="slider-label">Light intensity <b>{ppfd} µmol</b><input type="range" min="100" max="1200" step="20" bind:value={ppfd}/></label><label class="slider-label">Photoperiod <b>{hours} hours</b><input type="range" min="4" max="20" bind:value={hours}/></label><div class="note-box">ⓘ &nbsp; Planning estimate only. Local wind, radiation and crop stage affect actual irrigation.</div></article></section>
{:else if page==='Bio radar'}<section class="module-grid"><article class="card module-main"><div class="eyebrow">BIO-ACOUSTIC CLASSIFIER · 80–3,500 HZ</div><h2>Field listening station</h2><div class="big-reading">{activeInsect.hz.toLocaleString()} <small>Hz</small><span class="status-tag good"><i></i>{activeInsect.name.toUpperCase()}</span></div><div class="large-wave">{#each Array(80) as _,i}<i style={`height:${8+Math.abs(Math.sin(i*.29))*55+Math.random()*12}px`}></i>{/each}</div><p class="muted">Synthesized reference tone for demonstration. Insect identification from a phone microphone is an estimate, not a species-confirmed diagnosis.</p><button class="camera-button" on:click={startMic}>◉ &nbsp; Enable live microphone FFT</button></article><article class="card controls"><div class="eyebrow">REFERENCE SIGNATURES</div><h2>Choose a signature</h2>{#each insects as insect,i}<button class="reference-row" on:click={()=>play(insect)}><span class="insect-dot"></span><span><strong>{insect.name}</strong><small>{insect.kind}</small></span><b>{insect.hz} Hz →</b></button>{/each}<button class="outline-button full" on:click={stopTone}>Stop reference tone</button></article></section>
{:else if page==='NPK planner'}<section class="module-grid"><article class="card module-main"><div class="eyebrow">SOIL & IRRIGATION PRESCRIPTION</div><h2>Crop nutrient starting point</h2><label class="select-label">CROP PROFILE<select bind:value={crop}>{#each Object.keys(profiles) as p}<option>{p}</option>{/each}</select></label><div class="npk-cards">{#each [['NITROGEN',profiles[crop].n,'#9de7bd'],['PHOSPHORUS',profiles[crop].p,'#d5b6ff'],['POTASSIUM',profiles[crop].k,'#ffd08b']] as n}<div><span>{n[0]}</span><strong>{n[1]}</strong><small>ppm target</small></div>{/each}</div><div class="result-row"><div><small>TARGET pH</small><strong>{profiles[crop].ph}</strong></div><div><small>GUIDE EC</small><strong>{profiles[crop].ec} <em>mS/cm</em></strong></div><div><small>LEAF SPAD INPUT</small><strong>{sim.spad.toFixed(1)} <em>SPAD</em></strong></div></div><div class="note-box">ⓘ &nbsp; Starting targets only. Confirm with a soil or nutrient-solution test; follow product labels.</div></article><article class="card controls"><div class="eyebrow">CONNECTED OBSERVATION</div><h2>Recent leaf scan</h2><div class="linked-scan"><span class="leaf-icon">✳</span><span><strong>{sim.name}</strong><small>SPAD chlorophyll estimate</small></span><b>{sim.spad.toFixed(1)}</b></div><button class="outline-button full" on:click={()=>page='Leaf lab'}>Update leaf scan →</button></article></section>
{:else}<section class="card vault-card"><div class="card-top"><div><div class="eyebrow">LOCAL-FIRST · INDEXEDDB</div><h2>Field observation ledger</h2></div><button class="outline-button" on:click={exportCsv}>↓ Export CSV</button></div><p class="muted">Records stay on this device. Sync controls and source inspection are available to the director role.</p><div class="vault-stat"><strong>{records}</strong><span>observations saved this session</span></div><button class="camera-button" on:click={()=>saveRecord({type:'leaf',...sim}).then(getRecords).then(r=>records=r.length)}>＋ Save current leaf observation</button></section>{/if}
<div class="footer-line"><span>◈ &nbsp; SCIENCE-LED. FIELD-READY.</span><span>CALCULATIONS ARE ESTIMATES · VERIFY BEFORE TREATMENT</span><span>v1.0.0 <i>●</i> LOCAL MODE READY</span></div></main></div>
<nav class="mobile-dock">{#each nav.slice(0,4) as item}<button class:active={page===item[1]} on:click={()=>page=item[1]}><span>{item[0]}</span><small>{item[1].split(' ')[0]}</small></button>{/each}<a href="https://github.com/kennedy-blip/terra-spectra/releases/latest/download/TerraSpectra-AgroLab-v1.0.0.apk" download="TerraSpectra-AgroLab-v1.0.0.apk" on:click={()=>modal='APK center'} aria-label="Download Android APK"><span>↓</span><small>APK</small></a></nav>
{#if modal}<div class="modal-backdrop" role="presentation" on:click={(e)=>{if(e.target===e.currentTarget)modal=''}}><section class="modal card" role="dialog" aria-modal="true"><button class="modal-close" on:click={()=>modal=''}>×</button><div class="eyebrow">TERRA—SPECTRA</div><h2>{modal}</h2>{#if modal==='APK center'}<p>Download the Android package built by the GitHub release pipeline. The package is a debug-key-signed sideload build; it installs on Android but is not suitable for Play Store publishing or seamless upgrades between builds.</p><div class="apk-spec"><span>ANDROID APK · ARM / DEVICE-COMPATIBLE DEBUG BUILD</span><strong>Svelte · JavaScript · Capacitor + Kotlin</strong><small>SHA-256 checksum is attached to each GitHub release. Android may ask you to allow installs from your browser.</small></div><a class="camera-button apk-download-link" href="https://github.com/kennedy-blip/terra-spectra/releases/latest/download/TerraSpectra-AgroLab-v1.0.0.apk" download="TerraSpectra-AgroLab-v1.0.0.apk">↓ &nbsp; Download APK <span>GitHub release →</span></a><button class="text-button" on:click={()=>modal=''}>Continue in browser</button>{:else if modal==='Privileges'}<p>Choose your workspace access level. Role selection only changes the local interface; it does not provide security controls.</p>{#each ['Home gardener','Precision agronomist','Agri-systems director'] as r}<button class="reference-row" on:click={()=>{role=r;modal=''}}><span class="insect-dot"></span><span><strong>{r}</strong><small>{r==='Home gardener'?'Leaf scans, radar, VPD and watering':r==='Precision agronomist'?'Nutrient planning and crop models':'Runtime and local ledger tools'}</small></span><b>→</b></button>{/each}{:else}<p>{sim.name}: estimated chlorophyll {sim.spad.toFixed(1)} SPAD · VARI {sim.vari.toFixed(2)} · observed stress area {sim.blight.toFixed(1)}%.</p><div class="note-box">Camera-derived color indices are not calibrated SPAD measurements. Lighting, cultivar, white balance, and leaf age can change results substantially.</div>{#if permission==='CAMERA ACTIVE'}<button class="camera-button" on:click={()=>{clearInterval(scanTimer);scanTimer=null;mediaStream?.getTracks().forEach(t=>t.stop());mediaStream=null;permission='SIMULATOR ACTIVE';live=false;modal=''}}>Stop camera and save observation →</button>{:else}<button class="camera-button" on:click={()=>{modal='';startCamera()}}>Start camera scan →</button>{/if}<button class="text-button" on:click={()=>modal=''}>Close analysis</button>{/if}</section></div>{/if}</div>
